#[derive(Debug, Clone, PartialEq, serde::Serialize)]
#[serde(tag = "_variant")]
pub enum GrantRedemption {
    GrantRedemptionAdmitted {
        id: EventId,
        attempts_used: i64,
    },
    GrantRedemptionRefused {
        cause: Rc<RedemptionRefusal>,
    },
    GrantRedemptionContended {
        attempts: i64,
    },
    GrantRedemptionStoreRefused {
        cause: Rc<EventLogRefusal>,
    },
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
#[serde(tag = "_variant")]
pub enum RedemptionReading {
    RedemptionReadAt {
        head: Rc<HeadExpectation>,
        state: Rc<RedemptionState>,
    },
    RedemptionReadRefused {
        cause: Rc<EventLogRefusal>,
    },
}

pub async fn fabric_redemption_read(store: Rc<FabricStorageBinding>, pool_partition: NonEmptyStr, reference: String, filesystem: &Filesystem, shell_env: &Shell__Env, clock: &Clock, http_client: &Http__Client) -> std::result::Result<Rc<RedemptionReading>, std::boxed::Box<dyn std::error::Error>> {
    Ok(match (*event_log_read_partition_with(store, crate::product_capacity_redemption::redemption_partition_of(pool_partition), event_log_read_budget(), |t| crate::product_capacity_redemption::redemption_event_decode(t), filesystem, shell_env, clock, http_client).await?).clone() {
    PartitionRead::PartitionReadRefused { cause: c, .. } => Rc::new(RedemptionReading::RedemptionReadRefused {
    cause: c.clone(),
}),
    PartitionRead::PartitionReadOk { head: h, walk: w, .. } => Rc::new(RedemptionReading::RedemptionReadAt {
    head: h.clone(),
    state: crate::product_capacity_redemption::redemption_state_of(w.clone(), reference),
}),
})
}

pub async fn redemption_transition_attempt(store: Rc<FabricStorageBinding>, pool_partition: NonEmptyStr, reference: String, attempt: Nat, propose: impl Fn(Rc<RedemptionState>, Rc<HeadExpectation>) -> Rc<RedemptionProposal> + Clone, filesystem: &Filesystem, shell_env: &Shell__Env, clock: &Clock, http_client: &Http__Client) -> std::result::Result<Option<Rc<GrantRedemption>>, std::boxed::Box<dyn std::error::Error>> {
    Ok(match (*fabric_redemption_read(store.clone(), pool_partition.clone(), reference, filesystem, shell_env, clock, http_client).await?).clone() {
    RedemptionReading::RedemptionReadRefused { cause: c, .. } => Some(Rc::new(GrantRedemption::GrantRedemptionStoreRefused {
    cause: c.clone(),
})),
    RedemptionReading::RedemptionReadAt { head: h, state: s, .. } => match (*propose(s.clone(), h.clone())).clone() {
    RedemptionProposal::RedemptionRefused { cause: why, .. } => Some(Rc::new(GrantRedemption::GrantRedemptionRefused {
    cause: why.clone(),
})),
    RedemptionProposal::RedemptionProposed { event: e, expected: x, .. } => match (*event_log_append_with(store.clone(), crate::product_capacity_redemption::redemption_partition_of(pool_partition.clone()), e.clone(), x.clone(), |ev| crate::product_capacity_redemption::redemption_event_wire_text(ev), filesystem, shell_env, clock, http_client).await?).clone() {
    EventAppend::EventAppended { id: i, .. } => Some(Rc::new(GrantRedemption::GrantRedemptionAdmitted {
    id: i.clone(),
    attempts_used: attempt.clone(),
})),
    EventAppend::EventAppendStale { .. } => std::option::Option::None,
    EventAppend::EventAppendRefused { cause: c, .. } => Some(Rc::new(GrantRedemption::GrantRedemptionStoreRefused {
    cause: c.clone(),
})),
},
},
})
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct RedemptionAttemptState {
    pub done: Option<Rc<GrantRedemption>>,
}

pub async fn fabric_redemption_transition(store: Rc<FabricStorageBinding>, pool_partition: NonEmptyStr, reference: String, attempts: Nat, propose: impl Fn(Rc<RedemptionState>, Rc<HeadExpectation>) -> Rc<RedemptionProposal> + Clone, filesystem: &Filesystem, shell_env: &Shell__Env, clock: &Clock, http_client: &Http__Client) -> std::result::Result<Rc<GrantRedemption>, std::boxed::Box<dyn std::error::Error>> {
    let st = { let mut __fold_acc: Rc<RedemptionAttemptState> = Rc::new(RedemptionAttemptState {
    done: std::option::Option::None,
}); for __fold_elem in crate::std_nat::nat_range_inclusive(1, attempts.clone()).iter().cloned() { let acc = __fold_acc; let i = __fold_elem; __fold_acc = { match acc.done.clone() {
    Some(_) => acc.clone(),
    std::option::Option::None => Rc::new(RedemptionAttemptState {
    done: redemption_transition_attempt(store.clone(), pool_partition.clone(), reference.clone(), i.clone(), propose.clone(), filesystem, shell_env, clock, http_client).await?,
}),
} }; } __fold_acc };
Ok(match st.done.clone() {
    Some(done) => done.clone(),
    std::option::Option::None => Rc::new(GrantRedemption::GrantRedemptionContended {
    attempts: attempts.clone(),
}),
})
}

pub async fn fabric_grant_redeem(store: Rc<FabricStorageBinding>, pool_partition: NonEmptyStr, reference: String, request: String, holder: String, actor: String, at: i64, filesystem: &Filesystem, shell_env: &Shell__Env, clock: &Clock, http_client: &Http__Client) -> std::result::Result<Rc<GrantRedemption>, std::boxed::Box<dyn std::error::Error>> {
    Ok(fabric_redemption_transition(store, pool_partition.clone(), reference.clone(), 3, |state, head| crate::product_capacity_redemption::propose_redemption(state, head, crate::product_capacity_redemption::redemption_partition_of(pool_partition.clone()), at.clone(), actor.clone(), reference.clone(), request.clone(), holder.clone()), filesystem, shell_env, clock, http_client).await?)
}

pub async fn fabric_grant_use_end(store: Rc<FabricStorageBinding>, pool_partition: NonEmptyStr, reference: String, request: String, outcome: String, actor: String, at: i64, filesystem: &Filesystem, shell_env: &Shell__Env, clock: &Clock, http_client: &Http__Client) -> std::result::Result<Rc<GrantRedemption>, std::boxed::Box<dyn std::error::Error>> {
    Ok(fabric_redemption_transition(store, pool_partition.clone(), reference.clone(), 3, |state, head| crate::product_capacity_redemption::propose_use_end(state, head, crate::product_capacity_redemption::redemption_partition_of(pool_partition.clone()), at.clone(), actor.clone(), reference.clone(), request.clone(), outcome.clone()), filesystem, shell_env, clock, http_client).await?)
}

pub fn grant_redemption_wire(r: Rc<GrantRedemption>) -> String {
    match (*r.clone()).clone() {
    GrantRedemption::GrantRedemptionAdmitted { id: i, attempts_used: n, .. } => Rc::new(vec!["redemption transition admitted as ".to_string(), i.clone(), " on attempt ".to_string(), (n.clone()).to_string()]).join(&"".to_string()),
    GrantRedemption::GrantRedemptionRefused { cause: c, .. } => crate::product_capacity_redemption::redemption_refusal_wire(c.clone()),
    GrantRedemption::GrantRedemptionContended { attempts: n, .. } => Rc::new(vec!["the redemption compare-and-set was contended ".to_string(), (n.clone()).to_string(), " times".to_string()]).join(&"".to_string()),
    GrantRedemption::GrantRedemptionStoreRefused { cause: c, .. } => Rc::new(vec!["fabric DB: ".to_string(), event_log_refusal_wire(c.clone())]).join(&"".to_string()),
}
}
